PROHIBITED = {"manipulation", "exploit_vulnerability", "social_scoring",
              "workplace_emotion_recognition", "untargeted_face_scraping"}
ANNEX_III = {"creditworthiness", "life_health_insurance_pricing", "recruitment",
             "education_access", "critical_infrastructure"}
TRANSPARENCY = {"chatbot", "synthetic_content", "deepfake"}

def classify(use_case: str, affects_eu: bool, role: str) -> dict:
    if not affects_eu:
        return {"tier": "out of scope", "note": "check again if EU users are added"}
    if use_case in PROHIBITED:
        return {"tier": "prohibited", "since": "2025-02-02", "fine": "EUR 35m or 7%"}
    if use_case in ANNEX_III:
        duties = (["risk management", "data governance", "technical documentation",
                   "logging", "accuracy and robustness", "conformity assessment"]
                  if role == "provider" else
                  ["use as instructed", "human oversight", "keep logs",
                   "inform affected people", "fundamental-rights impact assessment"])
        return {"tier": "high-risk", "from": "2027-12-02", "duties": duties}
    if use_case in TRANSPARENCY:
        return {"tier": "transparency", "from": "2026-08-02",
                "duties": ["tell people they are dealing with AI", "label synthetic content"]}
    return {"tier": "minimal", "duties": ["AI literacy for staff"]}
